// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

export interface OpenShiftIn {
  node: "MainReception" | "PharmacyCounter" | "LabReception" | "IPDBilling" | "EmergencyCounter" | "CashierDesk";
  opening_float?: number | string;
}

export interface CashShiftOut {
  shift_id: number;
  user_id: number;
  /** The cash counter */
  node: "MainReception" | "PharmacyCounter" | "LabReception" | "IPDBilling" | "EmergencyCounter" | "CashierDesk";
  terminal_id: number | null;
  opening_float: number;
  expected_cash: number;
  declared_cash: number | null;
  status: "Open" | "PendingCollection" | "Verified";
  opened_at: string;
  closed_at: string | null;
  business_date: string;
}

/** A shift with the expected cash by transaction type, non-cash collections and its cash drop. */
export interface CashShiftSummaryOut {
  shift_id: number;
  user_id: number;
  /** The cash counter */
  node: "MainReception" | "PharmacyCounter" | "LabReception" | "IPDBilling" | "EmergencyCounter" | "CashierDesk";
  terminal_id: number | null;
  opening_float: number;
  expected_cash: number;
  declared_cash: number | null;
  status: "Open" | "PendingCollection" | "Verified";
  opened_at: string;
  closed_at: string | null;
  business_date: string;
  cashier_name: string;
  by_type: ShiftTotalOut[];
  non_cash: NonCashTotalOut[];
  cash_drop: CashDropOut | null;
}

export interface ShiftTotalOut {
  txn_type: "Sale" | "ARCollection" | "Refund" | "WaiverDispensation" | "APPayout" | "Adjustment" | "CashDrop";
  count: number;
  total: number;
}

export interface NonCashTotalOut {
  method: "Cash" | "Card" | "BankTransfer" | "PanelCredit" | "PayrollDeduction" | "Charity";
  count: number;
  total: number;
}

export interface CashDropOut {
  cash_drop_id: number;
  shift_id: number;
  verified_by: number;
  expected_cash: number;
  counted_cash: number;
  variance: number | null;
  is_dual_control_required: boolean;
  second_approver_id: number | null;
  second_approved_at: string | null;
  status: "AwaitingSecondApproval" | "Approved" | "Rejected";
  note: string | null;
  verified_at: string;
  row_version: number;
}

export interface ShiftTransactionOut {
  shift_txn_id: number;
  txn_type: "Sale" | "ARCollection" | "Refund" | "WaiverDispensation" | "APPayout" | "Adjustment" | "CashDrop";
  amount: number;
  payment_id: number | null;
  receipt_no: string | null;
  invoice_id: number | null;
  ap_settlement_id: number | null;
  note: string | null;
  at: string;
}

export interface CloseShiftIn {
  /** Cash the cashier counted in the drawer (excluding the opening float) */
  declared_cash: number | string;
}

/** Open my cash shift at a counter — POST /api/v1/finance/cash-shifts/open (permissions: finance.shift.operate). */
export function openShift(body: OpenShiftIn): Promise<CashShiftOut> {
  return api<CashShiftOut>("POST", `/finance/cash-shifts/open`, body, { idempotent: true });
}

/** My open shift (if any) — GET /api/v1/finance/cash-shifts/mine (permissions: finance.shift.operate). */
export function myShift(): Promise<CashShiftSummaryOut | null> {
  return api<CashShiftSummaryOut | null>("GET", `/finance/cash-shifts/mine`, undefined);
}

/** Drawer ledger of a shift — GET /api/v1/finance/cash-shifts/{shift_id}/transactions (permissions: finance.shift.operate, finance.shift.view_all). */
export function shiftTxns(shift_id: number): Promise<ShiftTransactionOut[]> {
  return api<ShiftTransactionOut[]>("GET", `/finance/cash-shifts/${shift_id}/transactions`, undefined);
}

/** Close shift → PendingCollection — POST /api/v1/finance/cash-shifts/{shift_id}/close (permissions: finance.shift.operate). */
export function closeShift(shift_id: number, body: CloseShiftIn): Promise<CashShiftSummaryOut> {
  return api<CashShiftSummaryOut>("POST", `/finance/cash-shifts/${shift_id}/close`, body);
}
